CeladonMartRoofLittleGirlText:
    call CeladonMartRoofScript_GetDrinksInBag
    mov al, [ebp + wFilteredBagItemsCount]
    test al, al
    jz .noDrinksInBag
    mov al, 1
    mov [ebp + wDoNotWaitForButtonPressAfterDisplayingText], al
